def binary_search(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid
        else:
            hi = mid
    return -1

class Counter:
    def __init__(self):
        self.value = 0
    def increment(self):
        self.value += 1

class Cache:
    def __init__(self):
        self._data = {}
    def get(self, key):
        return self._data.get(key)
    def set(self, key, value):
        self._data[key] = value

def get_user(cursor, username):
    query = f"SELECT * FROM users WHERE username = '{username}'"
    cursor.execute(query)
    return cursor.fetchone()

def safe_divide(a, b):
    try:
        return a / b
    except:
        pass

def append_to(item, target=[]):
    target.append(item)
    return target

def parse_value(s):
    if '.' in s:
        return float(s)
    return int(s)

class ResourceManager:
    def __init__(self):
        self.lock_a = threading.Lock()
        self.lock_b = threading.Lock()
    def acquire_both(self):
        self.lock_a.acquire()
        self.lock_b.acquire()
    def release_both(self):
        self.lock_b.release()
        self.lock_a.release()

def serve_file(base_dir, filename):
    path = os.path.join(base_dir, filename)
    with open(path, 'r') as f:
        return f.read()
